<?php declare(strict_types=1);use App\Config\Env;const BASE_PATH=__DIR__.'/..';spl_autoload_register(static function(string $class):void{$prefix='App\\';if(!str_starts_with($class,$prefix))return;$file=BASE_PATH.'/app/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_readable($file))require $file;});require_once BASE_PATH.'/app/Config/Env.php';Env::load(BASE_PATH.'/.env');date_default_timezone_set(Env::get('APP_TIMEZONE','Africa/Nairobi')??'Africa/Nairobi');$debug=filter_var(Env::get('APP_DEBUG','false'),FILTER_VALIDATE_BOOL);ini_set('display_errors',$debug?'1':'0');error_reporting(E_ALL);ini_set('session.use_strict_mode','1');ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Lax');if((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'))ini_set('session.cookie_secure','1');if(session_status()!==PHP_SESSION_ACTIVE)session_start();if(PHP_SAPI!=='cli'&&!headers_sent()){header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: strict-origin-when-cross-origin');header('Permissions-Policy: camera=(), microphone=(), geolocation=(self)');}register_shutdown_function(static function():void{\App\Services\ActivityLogger::request();});